InvokeScript:
$OneDrivePath = $Env:OneDrive
$OneDriveFolderExists = -not [string]::IsNullOrWhiteSpace($OneDrivePath) -and (Test-Path -LiteralPath $OneDrivePath -PathType Container -ErrorAction Stop)

if ($OneDriveFolderExists) {
    $OneDriveAcl = Get-Acl -LiteralPath $OneDrivePath -ErrorAction Stop
} else {
    Write-Host "OneDrive folder is already absent; skipping folder permissions and cleanup."
}

try {
    if ($OneDriveFolderExists) {
        # Protect user files while the uninstaller runs.
        icacls $OneDrivePath /deny "*S-1-5-32-544:(D,DC)"
        if ($LASTEXITCODE -ne 0) { throw "Unable to protect the OneDrive folder (icacls exit code $LASTEXITCODE)." }
    }

    Write-Host "Uninstalling OneDrive..."
    Start-Process -FilePath (Join-Path $Env:SystemRoot "System32\OneDriveSetup.exe") -ArgumentList '/uninstall' -Wait -ErrorAction Stop

    # Some of OneDrive files use explorer, and OneDrive uses FileCoAuth
    Write-Host "Removing leftover OneDrive Files..."

    Get-Process -ErrorAction Stop | Where-Object ProcessName -eq 'FileCoAuth' | Stop-Process -ErrorAction Stop
    Get-Process -ErrorAction Stop | Where-Object ProcessName -eq 'Explorer' | Stop-Process -ErrorAction Stop

    $OneDriveLeftovers = @("$Env:LocalAppData\Microsoft\OneDrive", "$Env:ProgramData\Microsoft OneDrive")
    foreach ($LeftoverPath in $OneDriveLeftovers) {
        if (Test-Path -LiteralPath $LeftoverPath -ErrorAction Stop) {
            Remove-Item -LiteralPath $LeftoverPath -Recurse -Force -ErrorAction Stop
        }
    }
} finally {
    if ($OneDriveFolderExists) {
        # Restore access even when uninstall or leftover cleanup fails.
        Set-Acl -LiteralPath $OneDrivePath -AclObject $OneDriveAcl -ErrorAction Stop
    }
}

if ($OneDriveFolderExists -and -not (Get-ChildItem -LiteralPath $OneDrivePath -Force -ErrorAction Stop)) {
    # Refuse to delete if files appeared after the emptiness check.
    [System.IO.Directory]::Delete($OneDrivePath, $false)
    [Environment]::SetEnvironmentVariable('OneDrive', $null, 'User')
}

# OneSyncSvc is a per-user template; Get-Service only exposes user instances.
# Skip the operation if this Windows installation has no template.
if (Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\OneSyncSvc') {
    Set-Service -Name OneSyncSvc -StartupType Disabled
}

UndoScript:
Write-Host "Installing OneDrive"
winget install Microsoft.Onedrive --source winget

# Enable OneSyncSvc when the per-user service template exists
if (Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\OneSyncSvc') {
    Set-Service -Name OneSyncSvc -StartupType Automatic
}

InvokeScript:
if (-not (Get-ComputerRestorePoint)) {
    Enable-ComputerRestore -Drive $Env:SystemDrive
}

Checkpoint-Computer -Description "System Restore Point created by WinUtil" -RestorePointType MODIFY_SETTINGS
Write-Host "System Restore Point Created Successfully" -ForegroundColor Green

# The Spotlight policies only apply to Enterprise and Education, so on other editions this
# makes the same changes Settings makes when the background is switched to Picture
$spotlightSettings = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\DesktopSpotlight\Settings'
$wallpapers = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers'
$spotlightIcon = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Desktop\NameSpace\{2cc5ca98-6485-489a-920e-b3e88a6ccce3}'
$enabledState = (Get-ItemProperty -Path $spotlightSettings -ErrorAction SilentlyContinue).EnabledState
$backgroundType = (Get-ItemProperty -Path $wallpapers -ErrorAction SilentlyContinue).BackgroundType
if ($enabledState -eq 1 -or $backgroundType -eq 3) {
    $systemLight = (Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -ErrorAction SilentlyContinue).SystemUsesLightTheme
    $image = if ($systemLight -eq 0) { 'img19.jpg' } else { 'img0.jpg' }
    $wallpaper = Join-Path $Env:SystemRoot "Web\Wallpaper\Windows\$image"

    if (-not ([System.Management.Automation.PSTypeName]'WinUtilWallpaper').Type) {
        Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class WinUtilWallpaper { [DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)] public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, string pvParam, uint fWinIni); }'
    }

    # SPI_SETDESKWALLPAPER = 0x0014; SPIF_UPDATEINIFILE | SPIF_SENDCHANGE = 3
    if (-not [WinUtilWallpaper]::SystemParametersInfo(0x0014, 0, $wallpaper, 3)) {
        throw "Could not set $wallpaper as the desktop wallpaper (Win32 error $([System.Runtime.InteropServices.Marshal]::GetLastWin32Error()))."
    }

    # A new wallpaper alone leaves Spotlight mode on: BackgroundType 0 is Picture (3 is Spotlight)
    if (-not (Test-Path -Path $wallpapers)) { New-Item -Path $wallpapers -Force | Out-Null }
    Set-ItemProperty -Path $wallpapers -Name BackgroundType -Value 0 -Type DWord
    if (Test-Path -Path $spotlightSettings) {
        Set-ItemProperty -Path $spotlightSettings -Name EnabledState -Value 0 -Type DWord
    }
    # The "Learn about this picture" desktop icon
    if (Test-Path -LiteralPath $spotlightIcon) {
        Remove-Item -LiteralPath $spotlightIcon -Recurse -Force
    }
    Invoke-WinUtilExplorerUpdate -action "restart"

    Write-Host "Replaced the Windows Spotlight desktop background with $wallpaper"
} else {
    Write-Host 'Windows Spotlight is not the desktop background; the wallpaper was left unchanged.'
}

# The pinned list lives in the Taskband key and the User Pinned\TaskBar shortcuts. Deleting the
# key makes Explorer rebuild it with default pins, so the key is kept and marked empty instead
$taskband = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband'
$pinnedFolder = Join-Path $Env:APPDATA 'Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar'
$backup = Join-Path $Env:LOCALAPPDATA 'winutil\backup\TaskbarPins'

# The first backup is kept, so applying again does not replace the pins Undo restores
if (-not (Test-Path -LiteralPath $backup)) {
    New-Item -ItemType Directory -Path (Join-Path $backup 'TaskBar') -Force | Out-Null
    if (Test-Path -Path $taskband) {
        reg.exe export 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband' (Join-Path $backup 'Taskband.reg') /y | Out-Null
        if ($LASTEXITCODE -ne 0) {
            Remove-Item -LiteralPath $backup -Recurse -Force
            throw "Could not back up the taskbar pins (reg.exe exit code $LASTEXITCODE)."
        }
    }
    if (Test-Path -LiteralPath $pinnedFolder) {
        Get-ChildItem -LiteralPath $pinnedFolder -File | Copy-Item -Destination (Join-Path $backup 'TaskBar') -Force -ErrorAction Stop
    }
}

# Explorer writes the pinned list back when it exits, so change it while Explorer is stopped
Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
if (Test-Path -LiteralPath $pinnedFolder) {
    Get-ChildItem -LiteralPath $pinnedFolder -File | Remove-Item -Force
}
if (-not (Test-Path -Path $taskband)) { New-Item -Path $taskband -Force | Out-Null }
Set-ItemProperty -Path $taskband -Name Favorites -Value ([byte[]](0xFF)) -Type Binary
Remove-ItemProperty -Path $taskband -Name FavoritesResolve -ErrorAction SilentlyContinue
Start-Process explorer.exe

Write-Host "Removed the taskbar pins. Undo restores them from $backup"

# Start reads ConfigureStartPins only when it builds a new layout, and on Pro only from the Group
# Policy location. Start rebuilds its layout under an empty pinned list, and the policy is then
# put back as it was, so pins added later are kept.
$localState = Join-Path $Env:LOCALAPPDATA 'Packages\Microsoft.Windows.StartMenuExperienceHost_cw5n1h2txyewy\LocalState'
$backup = Join-Path $Env:LOCALAPPDATA 'winutil\backup\StartPins'
$policyKey = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Explorer'

$layoutFiles = @(Get-ChildItem -LiteralPath $localState -Filter 'start*.bin' -File -ErrorAction SilentlyContinue)
if ($layoutFiles.Count -eq 0) {
    throw "No Start layout file was found in $localState."
}

# The first backup is kept, so applying again does not replace the pins Undo restores
if (-not (Test-Path -LiteralPath $backup)) {
    New-Item -ItemType Directory -Path $backup -Force | Out-Null
    $layoutFiles | Copy-Item -Destination $backup -Force -ErrorAction Stop
}

$previousPolicy = (Get-ItemProperty -Path $policyKey -Name ConfigureStartPins -ErrorAction SilentlyContinue).ConfigureStartPins
if (-not (Test-Path -Path $policyKey)) { New-Item -Path $policyKey -Force | Out-Null }
New-ItemProperty -Path $policyKey -Name ConfigureStartPins -Value '{"applyOnce":true,"pinnedList":[]}' -PropertyType String -Force | Out-Null

try {
    Stop-Process -Name StartMenuExperienceHost -Force -ErrorAction SilentlyContinue
    Start-Sleep -Milliseconds 500
    $layoutFiles | Remove-Item -Force -ErrorAction Stop
    # Windows starts Start again by itself and writes a new layout
    Stop-Process -Name StartMenuExperienceHost -Force -ErrorAction SilentlyContinue

    $deadline = (Get-Date).AddSeconds(20)
    while (-not (Get-ChildItem -LiteralPath $localState -Filter 'start*.bin' -File -ErrorAction SilentlyContinue) -and (Get-Date) -lt $deadline) {
        Start-Sleep -Milliseconds 500
    }
    if (-not (Get-ChildItem -LiteralPath $localState -Filter 'start*.bin' -File -ErrorAction SilentlyContinue)) {
        Write-Warning 'Start did not rebuild its layout in time; open Start once to finish, or run Undo to restore the previous pins.'
        Write-WinUtilLog -Level 'WARN' -Component 'Script' -Message 'Start did not rebuild its layout within 20 seconds.'
    }
    Start-Sleep -Seconds 2
} finally {
    if ($null -ne $previousPolicy) {
        New-ItemProperty -Path $policyKey -Name ConfigureStartPins -Value $previousPolicy -PropertyType String -Force | Out-Null
    } else {
        Remove-ItemProperty -Path $policyKey -Name ConfigureStartPins -ErrorAction SilentlyContinue
    }
}

Write-Host "Removed the Start menu pins. Undo restores them from $backup"

Stop-Process -Name "logi_download_assistant" -Force -ErrorAction SilentlyContinue

$ProgramFiles64 = if ($Env:ProgramW6432) { $Env:ProgramW6432 } else { $Env:ProgramFiles }
$LogiPath = "$ProgramFiles64\LogiDownloadAssistant"

if (Test-Path $LogiPath) {
  Remove-Item $LogiPath\* -Recurse -Force
} else {
  New-Item -Path $LogiPath -ItemType Directory
}

icacls $LogiPath /deny "*S-1-1-0:(W)"
if ($LASTEXITCODE -ne 0) { throw "icacls failed to deny write access on $LogiPath (exit code $LASTEXITCODE)" }

UndoScript:
$ProgramFiles64 = if ($Env:ProgramW6432) { $Env:ProgramW6432 } else { $Env:ProgramFiles }
$LogiPath = "$ProgramFiles64\LogiDownloadAssistant"

if (Test-Path $LogiPath) {
  icacls $LogiPath /remove:d "*S-1-1-0"
  if ($LASTEXITCODE -ne 0) { throw "icacls failed to remove the write-deny rule on $LogiPath (exit code $LASTEXITCODE)" }
}

